body:
I have a [PR](https://github.com/godotengine/godot/pull/115459) that fixes this issue!

The `_import` function of the above repro project needs to be modified to the following to see the effect.  I've marked my modifications with `#CHANGED` comments.
```gdscript
func _import(
	source_file: String,
	save_path: String,
	_options: Dictionary,
	_platform_variants: Array[String],
	_gen_files: Array[String]
) -> Error:
	var file := FileAccess.open(source_file, FileAccess.READ)
	var contents := file.get_as_text()

	var base_name := source_file.get_basename()

	var img_dir := "{0}_images".format([base_name])
	DirAccess.make_dir_recursive_absolute(img_dir)
	# EditorInterface.get_resource_filesystem().update_file(img_dir)  # CHANGED: This still does nothing.

	# spoof: extract images from file contents and put them in separate directory to reduce clutter
	var img_save_path := "{0}/image.png".format([img_dir])
	var img := Image.create_empty(256, 256, false, Image.Format.FORMAT_RGB8)
	img.save_png(img_save_path)
	EditorInterface.get_resource_filesystem().update_file(img_save_path) # This now works with my PR!
	append_import_external_resource(img_save_path, {}, "Texture2D") # CHANGED: Trigger the editor to reimport the image file.
	_gen_files.append(img_save_path)

	var texture_resource := ImageTexture.create_from_image(img) # CHANGED: Don't reimport the image here, just make a dummy resource that references the new save path.
	texture_resource.take_over_path(img_save_path) # CHANGED

	var top_node := TextureRect.new()
	top_node.texture = texture_resource
	top_node.name = contents

	var scene := PackedScene.new()
	scene.pack(top_node)

	return ResourceSaver.save(scene, "{0}.{1}".format([save_path, _get_save_extension()]))
```
